-- V25__seed_class_workouts_and_exercises.sql
-- Restoring and enriching class-based workouts (Zumba, Cardio Blast, Power Yoga, CrossFit)
-- Each exercise has been updated with a detailed, premium description.

-- 1. Insert 100 Class Exercises (Zumba, Cardio, Yoga, CrossFit)
INSERT INTO exercises (id, name, muscle_group, secondary_muscles, equipment, mechanics, difficulty_level, recommended_sets, recommended_reps, rest_interval, description, created_at)
VALUES
-- ZUMBA (101-125)
('e2500001-0000-0000-0000-000000000101', 'Zumba Warm-up', 'CARDIO', 'Full Body', 'Bodyweight', 'COMPOUND', 'BEGINNER', 1, '180s', '0s', 'Begin with basic marching in place combined with gentle arm swings to gradually raise your heart rate, improve blood circulation, and warm up your muscles. This low-impact movement prepares your body for the higher-energy Zumba routine while enhancing coordination and mobility.', NOW()),
('e2500001-0000-0000-0000-000000000102', 'Salsa Step', 'CARDIO', 'Core, Legs', 'Bodyweight', 'COMPOUND', 'BEGINNER', 1, '120s', '0s', 'Perform a foundational salsa side-to-side step to build rhythm and cardiovascular endurance. This dynamic lateral movement helps loosen up the hips while maintaining a steady calorie burn throughout the routine.', NOW()),
('e2500001-0000-0000-0000-000000000103', 'Merengue March', 'CARDIO', 'Hips, Calves', 'Bodyweight', 'COMPOUND', 'BEGINNER', 1, '120s', '0s', 'Engage in a fast-paced merengue marching movement emphasizing pronounced hip action and rapid footwork. This helps build core stability and lower-body agility, all while keeping your cardiovascular system working at an elevated rate.', NOW()),
('e2500001-0000-0000-0000-000000000104', 'Reggaeton Bounce', 'LEGS', 'Glutes, Core', 'Bodyweight', 'COMPOUND', 'INTERMEDIATE', 1, '120s', '0s', 'Drop into a deep rhythmic squat bounce that heavily targets the glutes and quadriceps. The constant pulsing tension forces lower-body muscular endurance while the musical beat dictates the pacing and intensity.', NOW()),
('e2500001-0000-0000-0000-000000000105', 'Cumbia Sleep', 'CARDIO', 'Core, Back', 'Bodyweight', 'COMPOUND', 'BEGINNER', 1, '120s', '0s', 'Execute a sweeping side-step motion paired with a full-arm drag, mimicking traditional Cumbia dance styling. This engages the obliques and rotational core muscles while maintaining a strong aerobic foundation.', NOW()),
('e2500001-0000-0000-0000-000000000106', 'Beto Shuffle', 'CARDIO', 'Calves, Core', 'Bodyweight', 'COMPOUND', 'INTERMEDIATE', 1, '60s', '0s', 'A signature high-speed footwork drill requiring quick lateral agility and ankle mobility. The Beto Shuffle sharply increases the heart rate and trains fast-twitch muscle fibers in the lower leg.', NOW()),
('e2500001-0000-0000-0000-000000000107', 'Destroza', 'CORE', 'Hips, Obliques', 'Bodyweight', 'ISOLATION', 'INTERMEDIATE', 1, '120s', '0s', 'Focus on deep hip isolation and fluid pelvic rotations to actively engage the abdominal wall. This intricate movement tones the core while providing excellent lower back and pelvic floor mobility.', NOW()),
('e2500001-0000-0000-0000-000000000108', 'Quebradita', 'LEGS', 'Core, Cardio', 'Bodyweight', 'COMPOUND', 'ADVANCED', 1, '120s', '0s', 'A high-impact jump kick movement that demands explosive power from the legs and precise core timing. This functions as a metabolic spike in the routine to push cardiovascular limits.', NOW()),
('e2500001-0000-0000-0000-000000000109', 'Soca Whine', 'CORE', 'Lower Back', 'Bodyweight', 'ISOLATION', 'BEGINNER', 1, '120s', '0s', 'Perform continuous, fluid hip circles and figure-eight rotations inspired by Soca music. This sustained isolation heavily recruits the deep core and oblique muscles while acting as active recovery for the lungs.', NOW()),
('e2500001-0000-0000-0000-000000000110', 'Calypso Jump', 'CARDIO', 'Quads, Calves', 'Bodyweight', 'COMPOUND', 'ADVANCED', 1, '60s', '0s', 'Execute high-energy, bounding jumps synced to a rapid Calypso rhythm. This plyometric-style cardio bursts maximizes fat burn and builds explosive lower body strength.', NOW()),
('e2500001-0000-0000-0000-000000000111', 'Bhangra Arms', 'SHOULDERS', 'Upper Back', 'Bodyweight', 'ISOLATION', 'INTERMEDIATE', 1, '120s', '0s', 'Maintain high overhead arm positions and rhythmic shoulder shrugging paired with leg lifts. This continuous overhead hold rapidly fatigues the deltoids, building shoulder endurance without any weights.', NOW()),
('e2500001-0000-0000-0000-000000000112', 'Flamenco Tap', 'CALVES', 'Ankles', 'Bodyweight', 'ISOLATION', 'BEGINNER', 1, '120s', '0s', 'Perform rapid, rhythmic heel-and-toe tapping focusing entirely on ankle dexterity and calf activation. This serves as great lower-leg conditioning and improves overall footwork speed.', NOW()),
('e2500001-0000-0000-0000-000000000113', 'Tango Lunge', 'LEGS', 'Glutes, Core', 'Bodyweight', 'COMPOUND', 'INTERMEDIATE', 1, '120s', '0s', 'Step into a deep, dramatic side lunge holding the bottom position for maximum quad and glute engagement. The dramatic pause builds isometric leg strength while maintaining dance posture.', NOW()),
('e2500001-0000-0000-0000-000000000114', 'Samba Roll', 'CORE', 'Hips, Spine', 'Bodyweight', 'COMPOUND', 'INTERMEDIATE', 1, '120s', '0s', 'Execute a full-body rolling movement that undulates from the chest down through the pelvis. This spinal articulation improves back flexibility and intensely works the anterior abdominal wall.', NOW()),
('e2500001-0000-0000-0000-000000000115', 'Belly Dance Shimmy', 'CORE', 'Shoulders, Hips', 'Bodyweight', 'ISOLATION', 'ADVANCED', 1, '60s', '0s', 'Perform ultra-fast, vibrating shoulder and hip shimmies requiring extreme muscular control and isolation. This forces high-frequency muscle contractions in the core and upper back.', NOW()),
('e2500001-0000-0000-0000-000000000116', 'Cha-Cha-Cha', 'CARDIO', 'Legs', 'Bodyweight', 'COMPOUND', 'BEGINNER', 1, '120s', '0s', 'A classic forward-and-back triple step sequence that keeps the heart rate steadily elevated. It focuses on maintaining a tight, bouncy rhythm to continuously work the calves and thighs.', NOW()),
('e2500001-0000-0000-0000-000000000117', 'Mambo Front', 'CARDIO', 'Hips', 'Bodyweight', 'COMPOUND', 'BEGINNER', 1, '120s', '0s', 'Perform a forward stepping motion that incorporates a brief hip check before returning to base. This builds cardiovascular endurance while establishing strong mind-muscle connection in the lower body.', NOW()),
('e2500001-0000-0000-0000-000000000118', 'Bachata Hip', 'CORE', 'Obliques', 'Bodyweight', 'ISOLATION', 'INTERMEDIATE', 1, '120s', '0s', 'Execute a subtle yet forceful hip pop on the fourth beat of the step sequence. This targeted movement isolates the obliques and lower abdominals, carving out core definition through repetition.', NOW()),
('e2500001-0000-0000-0000-000000000119', 'Axe Sway', 'LEGS', 'Core', 'Bodyweight', 'COMPOUND', 'INTERMEDIATE', 1, '120s', '0s', 'Combine a wide side-to-side body sway with alternating shallow lunges. This constant shifting of body weight places prolonged time-under-tension on the quadriceps and gluteus medius.', NOW()),
('e2500001-0000-0000-0000-000000000120', 'Dembow Beat', 'LEGS', 'Glutes, Core', 'Bodyweight', 'COMPOUND', 'ADVANCED', 1, '120s', '0s', 'Engage in a hard-hitting, aggressive squat pulse that matches a heavy reggaeton beat. This movement severely taxes the lower body musculature, functioning as a high-intensity resistance phase.', NOW()),
('e2500001-0000-0000-0000-000000000121', 'Kizomba Slow', 'CARDIO', 'Hips', 'Bodyweight', 'COMPOUND', 'BEGINNER', 1, '120s', '0s', 'A slow, grounded, partner-style stepping sequence focusing on body control and deceleration. It serves as an active recovery period to lower the heart rate while maintaining muscular engagement.', NOW()),
('e2500001-0000-0000-0000-000000000122', 'Jive Kick', 'LEGS', 'Cardio', 'Bodyweight', 'COMPOUND', 'ADVANCED', 1, '60s', '0s', 'Perform rapid, bouncing front and side kicks requiring high cardiovascular output and hamstring flexibility. This plyometric-heavy movement spikes the heart rate and challenges balance.', NOW()),
('e2500001-0000-0000-0000-000000000123', 'Swing Step', 'CARDIO', 'Legs', 'Bodyweight', 'COMPOUND', 'INTERMEDIATE', 1, '120s', '0s', 'Take a wide, bouncy stance moving dynamically from side to side with large arm swings. This full-body movement maximizes caloric burn and requires significant aerobic stamina.', NOW()),
('e2500001-0000-0000-0000-000000000124', 'Cool Down Stretch', 'RECOVERY', 'Full Body', 'Bodyweight', 'COMPOUND', 'BEGINNER', 1, '180s', '0s', 'Slowly transition into a series of static stretches focusing on lengthening the hamstrings, quads, and chest. This allows the heart rate to safely return to baseline while preventing post-workout muscle stiffness.', NOW()),
('e2500001-0000-0000-0000-000000000125', 'Deep Breath', 'RECOVERY', 'Lungs, Diaphragm', 'Bodyweight', 'ISOLATION', 'BEGINNER', 1, '120s', '0s', 'Conclude the routine with a mindful inhale and exhale flow, raising arms on the inhale and lowering on the exhale. This diaphragmatic breathing fully oxygenates the blood and centers the nervous system.', NOW()),

-- CARDIO BLAST (201-225)
('e2500001-0000-0000-0000-000000000201', 'Jumping Jacks', 'CARDIO', 'Calves, Shoulders', 'Bodyweight', 'COMPOUND', 'BEGINNER', 1, '60s', '0s', 'A classic full-body aerobic movement that rapidly elevates the heart rate and warms up the shoulder joints. By jumping the feet wide while raising the arms overhead, you engage the entire cardiovascular system.', NOW()),
('e2500001-0000-0000-0000-000000000202', 'High Knees', 'CARDIO', 'Core, Hip Flexors', 'Bodyweight', 'COMPOUND', 'INTERMEDIATE', 1, '45s', '0s', 'Run in place while driving your knees up to chest level as fast as possible. This intense plyometric drill targets the lower abs, hip flexors, and forces maximum aerobic output in a short timeframe.', NOW()),
('e2500001-0000-0000-0000-000000000203', 'Burpees', 'FULL BODY', 'Chest, Legs, Core', 'Bodyweight', 'COMPOUND', 'ADVANCED', 1, '45s', '0s', 'An explosive, total-body metabolic conditioning exercise moving from a standing position to a floor push-up, and ending with a vertical jump. It delivers unparalleled fat burning and muscular endurance benefits.', NOW()),
('e2500001-0000-0000-0000-000000000204', 'Mountain Climbers', 'CORE', 'Shoulders, Cardio', 'Bodyweight', 'COMPOUND', 'INTERMEDIATE', 1, '45s', '0s', 'Assume a high plank position and rapidly drive alternating knees toward your chest. This creates a massive metabolic spike while demanding extreme stability from your shoulders and core.', NOW()),
('e2500001-0000-0000-0000-000000000205', 'Squat Jumps', 'LEGS', 'Glutes, Calves', 'Bodyweight', 'COMPOUND', 'ADVANCED', 1, '45s', '0s', 'Descend into a full bodyweight squat before exploding upward into a maximum-height vertical jump. This plyometric movement builds immense lower-body power and torches calories rapidly.', NOW()),
('e2500001-0000-0000-0000-000000000206', 'Lunge Jumps', 'LEGS', 'Glutes, Core', 'Bodyweight', 'COMPOUND', 'ADVANCED', 1, '45s', '0s', 'Start in a lunge position, jump explosively into the air, and switch leg positions before landing softly into the next lunge. This requires advanced balance, coordination, and intense quad strength.', NOW()),
('e2500001-0000-0000-0000-000000000207', 'Butt Kicks', 'CARDIO', 'Hamstrings', 'Bodyweight', 'COMPOUND', 'BEGINNER', 1, '60s', '0s', 'Jog in place with a focus on kicking your heels directly up to your glutes. This serves as an excellent dynamic stretch for the quadriceps while keeping the heart rate in the fat-burning zone.', NOW()),
('e2500001-0000-0000-0000-000000000208', 'Skaters', 'LEGS', 'Core, Ankles', 'Bodyweight', 'COMPOUND', 'INTERMEDIATE', 1, '45s', '0s', 'Leap laterally from one foot to the other, sweeping the trailing leg behind you in a speed-skater motion. This builds lateral power, stabilizes the knee and ankle joints, and heavily recruits the gluteus medius.', NOW()),
('e2500001-0000-0000-0000-000000000209', 'Plank Jacks', 'CORE', 'Shoulders, Cardio', 'Bodyweight', 'COMPOUND', 'INTERMEDIATE', 1, '45s', '0s', 'Hold a rigid high plank position while jumping your feet wide and back together in a jumping jack motion. This movement forces the core to fight rotational forces while keeping the heart rate high.', NOW()),
('e2500001-0000-0000-0000-000000000210', 'Box Jumps', 'LEGS', 'Cardio, Core', 'Bodyweight', 'COMPOUND', 'ADVANCED', 1, '45s', '0s', 'Perform a deep squat and explode upward to land softly with both feet on an elevated box or platform. This pure plyometric movement develops immense fast-twitch muscle fiber response and vertical power.', NOW()),
('e2500001-0000-0000-0000-000000000211', 'Tuck Jumps', 'CORE', 'Legs, Cardio', 'Bodyweight', 'COMPOUND', 'ADVANCED', 1, '30s', '0s', 'Launch forcefully into the air and aggressively pull both knees directly up to your chest before landing. This highly taxing movement requires total core engagement and elite cardiovascular capacity.', NOW()),
('e2500001-0000-0000-0000-000000000212', 'Fast Feet', 'CARDIO', 'Calves', 'Bodyweight', 'COMPOUND', 'BEGINNER', 1, '60s', '0s', 'Lower into a quarter-squat athletic stance and run in place with extremely rapid, shallow steps. This agility drill improves ground contact time, foot speed, and spikes the heart rate instantly.', NOW()),
('e2500001-0000-0000-0000-000000000213', 'Lateral Shuffles', 'CARDIO', 'Legs, Hips', 'Bodyweight', 'COMPOUND', 'INTERMEDIATE', 1, '60s', '0s', 'Maintain a low athletic stance and quickly shuffle from side to side without crossing your feet. This drill enhances lateral agility, hip mobility, and conditions the abductor muscles.', NOW()),
('e2500001-0000-0000-0000-000000000214', 'Star Jumps', 'FULL BODY', 'Cardio', 'Bodyweight', 'COMPOUND', 'ADVANCED', 1, '30s', '0s', 'Drop into a crouched position and explode upward, extending your arms and legs out wide in mid-air to form a star shape. This full-body plyometric move maximizes power output and calorie burn.', NOW()),
('e2500001-0000-0000-0000-000000000215', 'Inchworms', 'CORE', 'Shoulders, Hamstrings', 'Bodyweight', 'COMPOUND', 'INTERMEDIATE', 1, '60s', '0s', 'Hinge at the hips to place hands on the floor, then walk them out to a plank position before walking them back in. This provides a deep active stretch for the hamstrings while building shoulder and core endurance.', NOW()),
('e2500001-0000-0000-0000-000000000216', 'Bear Crawls', 'FULL BODY', 'Core, Shoulders', 'Bodyweight', 'COMPOUND', 'ADVANCED', 1, '60s', '0s', 'Crawl forward and backward on your hands and toes while keeping your knees bent and hovering just inches off the floor. This grueling total-body movement demands extreme core stability and muscular endurance.', NOW()),
('e2500001-0000-0000-0000-000000000217', 'Crab Walk', 'FULL BODY', 'Triceps, Glutes', 'Bodyweight', 'COMPOUND', 'INTERMEDIATE', 1, '60s', '0s', 'Sit on the floor, bridge your hips up, and walk forward and backward using your hands and feet. This unique movement patterns targets the triceps, glutes, and challenges posterior chain mobility.', NOW()),
('e2500001-0000-0000-0000-000000000218', 'Frog Jumps', 'LEGS', 'Cardio', 'Bodyweight', 'COMPOUND', 'INTERMEDIATE', 1, '45s', '0s', 'Drop into a wide, deep squat to touch the floor, then explode forward and up into a broad jump. This animal-flow inspired movement builds dynamic leg power and hip flexibility.', NOW()),
('e2500001-0000-0000-0000-000000000219', 'Kickboxing Hooks', 'UPPER BODY', 'Core, Shoulders', 'Bodyweight', 'COMPOUND', 'BEGINNER', 1, '60s', '0s', 'Adopt a fighting stance and throw rapid, powerful shadow-boxing hook punches. By engaging the core to drive the rotation, you build upper body speed, coordination, and rotational power.', NOW()),
('e2500001-0000-0000-0000-000000000220', 'Uppercuts', 'UPPER BODY', 'Core, Biceps', 'Bodyweight', 'COMPOUND', 'BEGINNER', 1, '60s', '0s', 'Perform rapid, alternating shadow-boxing uppercuts focusing on driving power up from the hips through the shoulders. This cardiovascular drill heavily engages the core and upper back musculature.', NOW()),
('e2500001-0000-0000-0000-000000000221', 'Speed Skaters', 'LEGS', 'Cardio, Glutes', 'Bodyweight', 'COMPOUND', 'ADVANCED', 1, '45s', '0s', 'A faster, lower, more aggressive version of the standard skater leap. Minimize ground contact time to emphasize speed, agility, and massive anaerobic cardiovascular output.', NOW()),
('e2500001-0000-0000-0000-000000000222', 'Heisman Shuffle', 'CARDIO', 'Core, Legs', 'Bodyweight', 'COMPOUND', 'INTERMEDIATE', 1, '45s', '0s', 'Perform three quick lateral steps and pause, driving the inside knee high toward the chest in a classic football pose. This drill hones lateral acceleration, deceleration, and unilateral balance.', NOW()),
('e2500001-0000-0000-0000-000000000223', 'Switch Kicks', 'CARDIO', 'Core, Legs', 'Bodyweight', 'COMPOUND', 'ADVANCED', 1, '45s', '0s', 'Lean slightly back and perform rapid, alternating front kicks as fast as possible. This martial-arts inspired drill taxes the lower abdominals and hip flexors while keeping the heart rate pinned.', NOW()),
('e2500001-0000-0000-0000-000000000224', 'Sprint in Place', 'CARDIO', 'Full Body', 'Bodyweight', 'COMPOUND', 'ADVANCED', 1, '30s', '0s', 'Pump your arms aggressively and drive your knees in a maximum-effort, all-out stationary sprint. This acts as the ultimate metabolic finisher to empty the gas tank and maximize post-workout calorie burn.', NOW()),
('e2500001-0000-0000-0000-000000000225', 'Cool Down Walk', 'RECOVERY', 'Cardio', 'Bodyweight', 'COMPOUND', 'BEGINNER', 1, '180s', '0s', 'Slowly walk around the room while taking deep, measured breaths to safely lower the heart rate. This active recovery phase flushes lactic acid from the legs and prevents blood pooling.', NOW()),

-- POWER YOGA (301-325)
('e2500001-0000-0000-0000-000000000301', 'Childs Pose', 'FLEXIBILITY', 'Back, Hips', 'Bodyweight', 'ISOLATION', 'BEGINNER', 1, '120s', '0s', 'Kneel and sit back on your heels, stretching your arms forward and resting your forehead on the mat. This deeply restorative posture gently stretches the hips, thighs, and lower back while calming the central nervous system.', NOW()),
('e2500001-0000-0000-0000-000000000302', 'Cat-Cow', 'FLEXIBILITY', 'Spine, Core', 'Bodyweight', 'COMPOUND', 'BEGINNER', 1, '60s', '0s', 'Move fluidly between an arched back (Cat) and a dropped belly (Cow) while on all fours. This foundational spinal warmup increases vertebral mobility, stimulates the kidneys, and syncs breath with movement.', NOW()),
('e2500001-0000-0000-0000-000000000303', 'Downward Dog', 'FLEXIBILITY', 'Hamstrings, Shoulders', 'Bodyweight', 'COMPOUND', 'BEGINNER', 1, '60s', '0s', 'Press back into an inverted V-shape, driving your heels toward the floor and your chest toward your thighs. This iconic yoga posture builds shoulder strength while intensely stretching the entire posterior chain.', NOW()),
('e2500001-0000-0000-0000-000000000304', 'Ragdoll', 'FLEXIBILITY', 'Hamstrings, Lower Back', 'Bodyweight', 'ISOLATION', 'BEGINNER', 1, '60s', '0s', 'Stand and fold forward at the hips, letting your arms dangle or grabbing opposite elbows while keeping a soft bend in the knees. This releases severe tension in the lower back and decompresses the cervical spine.', NOW()),
('e2500001-0000-0000-0000-000000000305', 'Sun Salutation A', 'FULL BODY', 'Cardio, Core', 'Bodyweight', 'COMPOUND', 'INTERMEDIATE', 3, '180s', '0s', 'A dynamic, heat-building sequence flowing through Mountain Pose, Forward Fold, Chaturanga, Upward Dog, and Downward Dog. This continuous loop generates internal body heat, builds upper body strength, and links breath to motion.', NOW()),
('e2500001-0000-0000-0000-000000000306', 'Sun Salutation B', 'FULL BODY', 'Legs, Core', 'Bodyweight', 'COMPOUND', 'ADVANCED', 3, '180s', '0s', 'A more rigorous variation of the classic flow that incorporates Chair Pose and Warrior I. This sequence significantly elevates the heart rate and demands greater lower-body strength and cardiovascular endurance.', NOW()),
('e2500001-0000-0000-0000-000000000307', 'Warrior I', 'LEGS', 'Core, Shoulders', 'Bodyweight', 'COMPOUND', 'INTERMEDIATE', 1, '60s', '0s', 'Step into a deep forward lunge with the back foot planted at a 45-degree angle, reaching both arms powerfully overhead. This pose stretches the hip flexors of the back leg while building immense strength in the front quad.', NOW()),
('e2500001-0000-0000-0000-000000000308', 'Warrior II', 'LEGS', 'Hips, Core', 'Bodyweight', 'COMPOUND', 'INTERMEDIATE', 1, '60s', '0s', 'Open your hips to the side in a deep lunge, extending your arms parallel to the floor with a fierce gaze forward. This foundational standing pose develops deep hip rotation flexibility and prolonged muscular endurance.', NOW()),
('e2500001-0000-0000-0000-000000000309', 'Reverse Warrior', 'CORE', 'Obliques, Legs', 'Bodyweight', 'COMPOUND', 'INTERMEDIATE', 1, '45s', '0s', 'From Warrior II, sweep your front arm overhead and arch slightly backward, resting your back hand lightly on your rear leg. This creates a massive lateral stretch through the obliques and intercostal muscles.', NOW()),
('e2500001-0000-0000-0000-000000000310', 'Triangle Pose', 'LEGS', 'Obliques, Spine', 'Bodyweight', 'COMPOUND', 'INTERMEDIATE', 1, '60s', '0s', 'Straighten your front leg and reach forward before hinging down to place your hand on your shin or the floor, extending the other arm skyward. This deeply stretches the hamstrings and groins while opening the chest.', NOW()),
('e2500001-0000-0000-0000-000000000311', 'Extended Side Angle', 'CORE', 'Legs, Shoulders', 'Bodyweight', 'COMPOUND', 'INTERMEDIATE', 1, '60s', '0s', 'In a deep lunge, place your front forearm on your thigh or hand on the floor, extending your top arm overhead in a straight line with your back leg. This builds intense leg stamina while lengthening the entire side body.', NOW()),
('e2500001-0000-0000-0000-000000000312', 'Chair Pose', 'LEGS', 'Core, Back', 'Bodyweight', 'COMPOUND', 'INTERMEDIATE', 1, '60s', '0s', 'Sit back as if into an imaginary chair while reaching your arms strongly overhead, keeping your chest lifted. This powerful isometric hold fires up the quadriceps, glutes, and erector spinae.', NOW()),
('e2500001-0000-0000-0000-000000000313', 'Tree Pose', 'BALANCE', 'Legs, Core', 'Bodyweight', 'ISOLATION', 'BEGINNER', 1, '60s', '0s', 'Balance on one leg while placing the sole of your opposite foot on your inner thigh or calf, pressing hands together at your heart. This develops ankle stability, mental focus, and external hip rotation.', NOW()),
('e2500001-0000-0000-0000-000000000314', 'Eagle Pose', 'BALANCE', 'Shoulders, Hips', 'Bodyweight', 'COMPOUND', 'ADVANCED', 1, '60s', '0s', 'Wrap one leg tightly around the other while simultaneously intertwining your arms in front of your face, sinking into a squat. This complex balancing posture intensely stretches the upper back and outer hips while demanding extreme focus.', NOW()),
('e2500001-0000-0000-0000-000000000315', 'Warrior III', 'BALANCE', 'Hamstrings, Core', 'Bodyweight', 'COMPOUND', 'ADVANCED', 1, '45s', '0s', 'Hinge forward on one leg until your torso and extended back leg are perfectly parallel to the floor, forming a T-shape. This challenging balance pose builds unilateral hamstring strength and total posterior chain stability.', NOW()),
('e2500001-0000-0000-0000-000000000316', 'Half Moon', 'BALANCE', 'Hips, Core', 'Bodyweight', 'COMPOUND', 'ADVANCED', 1, '45s', '0s', 'Balance on one leg with your torso and hips rotated open to the side, one hand resting lightly on the floor and the other reaching up. This demands advanced core control, hip abductor strength, and proprioception.', NOW()),
('e2500001-0000-0000-0000-000000000317', 'Plank', 'CORE', 'Shoulders, Arms', 'Bodyweight', 'COMPOUND', 'BEGINNER', 1, '60s', '0s', 'Hold the top of a push-up position with a perfectly rigid, straight body line from head to heels. This foundational isometric hold develops essential core stability and shoulder endurance required for advanced poses.', NOW()),
('e2500001-0000-0000-0000-000000000318', 'Chaturanga', 'ARMS', 'Chest, Core', 'Bodyweight', 'COMPOUND', 'ADVANCED', 1, '30s', '0s', 'Lower down from high plank until your elbows are at a 90-degree angle, hovering just inches above the floor. This intensely taxing tricep and chest hold is the yoga equivalent of a highly disciplined half push-up.', NOW()),
('e2500001-0000-0000-0000-000000000319', 'Upward Dog', 'BACK', 'Chest, Core', 'Bodyweight', 'COMPOUND', 'INTERMEDIATE', 1, '30s', '0s', 'With your pelvis and thighs hovering off the mat, press through your hands to lift your chest and arch your spine backward. This provides a deep stretch to the abdominal wall and opens the heart center.', NOW()),
('e2500001-0000-0000-0000-000000000320', 'Boat Pose', 'CORE', 'Hip Flexors', 'Bodyweight', 'COMPOUND', 'INTERMEDIATE', 1, '60s', '0s', 'Balance on your sitting bones with your legs lifted straight at a 45-degree angle, forming a V-shape with your torso. This creates intense, shaking tension in the deep core and hip flexors.', NOW()),
('e2500001-0000-0000-0000-000000000321', 'Bridge Pose', 'GLUTES', 'Lower Back', 'Bodyweight', 'COMPOUND', 'BEGINNER', 1, '60s', '0s', 'Lie on your back with knees bent and drive through your heels to lift your hips toward the ceiling. This actively strengthens the glutes and lower back while passively stretching the chest and neck.', NOW()),
('e2500001-0000-0000-0000-000000000322', 'Wheel Pose', 'BACK', 'Chest, Shoulders', 'Bodyweight', 'COMPOUND', 'ADVANCED', 1, '45s', '0s', 'Place your hands by your ears and press up into a full, deep backbend, lifting your entire body off the floor. This elite-level posture requires extreme spinal flexibility and significant upper body pushing strength.', NOW()),
('e2500001-0000-0000-0000-000000000323', 'Pigeon Pose', 'HIPS', 'Glutes', 'Bodyweight', 'ISOLATION', 'INTERMEDIATE', 1, '120s', '0s', 'Fold forward over one bent leg while the other leg extends straight back behind you. This deeply restorative, long-hold stretch releases profound tension in the piriformis, glutes, and outer hips.', NOW()),
('e2500001-0000-0000-0000-000000000324', 'Happy Baby', 'HIPS', 'Lower Back', 'Bodyweight', 'ISOLATION', 'BEGINNER', 1, '60s', '0s', 'Lie on your back, grab the outside edges of your flexed feet, and gently pull your knees down toward your armpits. This playful cooling posture opens the inner groins and provides a gentle massage for the lumbar spine.', NOW()),
('e2500001-0000-0000-0000-000000000325', 'Savasana', 'RECOVERY', 'Mind, Nervous System', 'Bodyweight', 'ISOLATION', 'BEGINNER', 1, '300s', '0s', 'Lie completely flat and motionless on your back, letting all muscles relax and the breath return to its natural rhythm. This final resting pose is critical for allowing the body to absorb the physical benefits of the practice.', NOW()),

-- CROSSFIT (401-425)
('e2500001-0000-0000-0000-000000000401', 'Air Squats', 'LEGS', 'Glutes, Core', 'Bodyweight', 'COMPOUND', 'BEGINNER', 3, '20', '0s', 'Perform rapid, full-depth bodyweight squats ensuring the hip crease drops below the top of the knee. This foundational movement builds essential lower-body muscular endurance and prepares the joints for heavier barbell work.', NOW()),
('e2500001-0000-0000-0000-000000000402', 'Pull-ups (Kipping)', 'BACK', 'Biceps, Core', 'Bodyweight', 'COMPOUND', 'ADVANCED', 3, '10', '0s', 'Utilize a dynamic hip swing and powerful core snap to propel your chin over the pull-up bar. This gymnastic-style pull-up allows for higher volume and faster cycle rates during intense metabolic conditioning workouts.', NOW()),
('e2500001-0000-0000-0000-000000000403', 'Push-ups', 'CHEST', 'Triceps, Core', 'Bodyweight', 'COMPOUND', 'INTERMEDIATE', 3, '15', '0s', 'Execute strict push-ups, maintaining a rigid plank position while lowering the chest completely to the floor before pressing to full lockout. A crucial upper-body strength builder used extensively in high-rep metcons.', NOW()),
('e2500001-0000-0000-0000-000000000404', 'Sit-ups (AbMat)', 'CORE', 'Hip Flexors', 'Bodyweight', 'ISOLATION', 'BEGINNER', 3, '20', '0s', 'Using a contoured lumbar support mat, perform full-range-of-motion sit-ups by touching the floor behind your head and then touching your toes. This allows for rapid, high-volume core conditioning without severe lower back friction.', NOW()),
('e2500001-0000-0000-0000-000000000405', 'Double Unders', 'CARDIO', 'Calves, Shoulders', 'Equipment', 'COMPOUND', 'ADVANCED', 3, '50', '0s', 'Jump slightly higher than normal while rapidly spinning a jump rope so it passes under your feet twice per single jump. This highly technical skill heavily taxes the cardiovascular system and tests shoulder endurance.', NOW()),
('e2500001-0000-0000-0000-000000000406', 'Box Jumps', 'LEGS', 'Cardio', 'Equipment', 'COMPOUND', 'INTERMEDIATE', 3, '10', '0s', 'Drop into a quarter squat and explode upward, landing softly with two feet on top of a 20 or 24-inch plyometric box. You must stand to full hip extension at the top to complete this explosive power-building rep.', NOW()),
('e2500001-0000-0000-0000-000000000407', 'Wall Balls', 'FULL BODY', 'Legs, Shoulders', 'Equipment', 'COMPOUND', 'INTERMEDIATE', 3, '20', '0s', 'Descend into a full front squat holding a medicine ball, then explosively drive upward to launch the ball to a 10-foot target on the wall. This brutal, full-body movement uniquely taxes both the legs and the lungs simultaneously.', NOW()),
('e2500001-0000-0000-0000-000000000408', 'Kettlebell Swings', 'HIPS', 'Glutes, Back', 'Kettlebell', 'COMPOUND', 'INTERMEDIATE', 3, '20', '0s', 'Hinge at the hips and violently snap the pelvis forward to swing a heavy kettlebell up to eye level (Russian) or fully overhead (American). This develops immense posterior chain power and explosive hip drive.', NOW()),
('e2500001-0000-0000-0000-000000000409', 'Thrusters', 'FULL BODY', 'Legs, Shoulders', 'Barbell', 'COMPOUND', 'ADVANCED', 3, '15', '0s', 'Combine a heavy front squat directly into a push press in one fluid, continuous motion. Arguably the most metabolically demanding movement in CrossFit, it requires total body coordination and massive power output.', NOW()),
('e2500001-0000-0000-0000-000000000410', 'Burpees', 'FULL BODY', 'Cardio, Chest', 'Bodyweight', 'COMPOUND', 'INTERMEDIATE', 3, '15', '0s', 'Drop your chest and thighs completely to the floor, aggressively push up and snap your hips, and finish with a small jump and overhead clap. This is the ultimate test of raw grit and metabolic conditioning.', NOW()),
('e2500001-0000-0000-0000-000000000411', 'Toes to Bar', 'CORE', 'Back, Grip', 'Bodyweight', 'COMPOUND', 'ADVANCED', 3, '10', '0s', 'Hang from a pull-up bar, utilize a strong kip swing, and forcefully contract your abdominals to bring both feet up to touch the bar simultaneously. This requires significant core strength, grip endurance, and hamstring flexibility.', NOW()),
('e2500001-0000-0000-0000-000000000412', 'Deadlift', 'BACK', 'Legs, Glutes', 'Barbell', 'COMPOUND', 'ADVANCED', 3, '5', '0s', 'Lift a heavily loaded barbell from the floor to a fully locked-out standing position, maintaining a rigidly flat back. This is the ultimate builder of raw absolute strength and thick posterior chain muscle.', NOW()),
('e2500001-0000-0000-0000-000000000413', 'Clean', 'FULL BODY', 'Back, Legs', 'Barbell', 'COMPOUND', 'ADVANCED', 3, '5', '0s', 'Explosively pull a barbell from the floor and quickly drop underneath it, catching the bar on your front shoulders in a full squat. This Olympic weightlifting movement develops elite athletic power and speed.', NOW()),
('e2500001-0000-0000-0000-000000000414', 'Snatch', 'FULL BODY', 'Shoulders, Back', 'Barbell', 'COMPOUND', 'ADVANCED', 3, '3', '0s', 'In one explosive, uninterrupted motion, pull a barbell from the floor and catch it with straight arms locked out overhead while dropping into a deep squat. This is the pinnacle of speed, flexibility, and athletic coordination.', NOW()),
('e2500001-0000-0000-0000-000000000415', 'Overhead Squat', 'FULL BODY', 'Core, Shoulders', 'Barbell', 'COMPOUND', 'ADVANCED', 3, '5', '0s', 'Descend into a full-depth squat while holding a barbell locked out overhead with a wide grip. This exposes any mobility deficits and demands unparalleled core stability and shoulder flexibility.', NOW()),
('e2500001-0000-0000-0000-000000000416', 'Handstand Push-ups', 'SHOULDERS', 'Triceps, Core', 'Bodyweight', 'COMPOUND', 'ADVANCED', 3, '8', '0s', 'Kick up into an inverted handstand against a wall, lower your head to the floor, and press back up to full arm extension. This advanced gymnastic skill builds elite overhead pressing strength using only your body weight.', NOW()),
('e2500001-0000-0000-0000-000000000417', 'Pistol Squats', 'LEGS', 'Balance, Core', 'Bodyweight', 'ISOLATION', 'ADVANCED', 3, '6', '0s', 'Perform a deep, single-leg bodyweight squat, bringing your hamstring to your calf while keeping the non-working leg extended straight out. This requires exceptional unilateral strength, ankle mobility, and balance.', NOW()),
('e2500001-0000-0000-0000-000000000418', 'Rope Climbs', 'BACK', 'Arms, Grip', 'Equipment', 'COMPOUND', 'ADVANCED', 2, '1', '0s', 'Ascend a 15-foot suspended rope using a J-hook or S-wrap foot lock technique combined with powerful upper body pulls. This heavily tests grip strength, bicep power, and fearless determination.', NOW()),
('e2500001-0000-0000-0000-000000000419', 'Rowing', 'CARDIO', 'Back, Legs', 'Machine', 'COMPOUND', 'BEGINNER', 1, '300s', '0s', 'Strap into an ergometer and execute powerful, full-body strokes, driving forcefully with the legs before finishing with the arms. This is a staple low-impact, high-yield cardiovascular conditioning tool.', NOW()),
('e2500001-0000-0000-0000-000000000420', 'Assault Bike', 'CARDIO', 'Legs, Arms', 'Machine', 'COMPOUND', 'INTERMEDIATE', 1, '120s', '0s', 'Push and pull the handles while violently pedaling a fan-resistance bike. The harder you work, the harder the resistance becomes, creating arguably the most painful and effective metabolic stimulus in the gym.', NOW()),
('e2500001-0000-0000-0000-000000000421', 'Dumbbell Snatch', 'FULL BODY', 'Shoulders, Hips', 'Dumbbell', 'COMPOUND', 'INTERMEDIATE', 3, '10', '0s', 'Explosively pull a single heavy dumbbell from the floor directly to an overhead lockout in one motion, alternating arms each rep. This builds unilateral power and corrects left-to-right strength imbalances.', NOW()),
('e2500001-0000-0000-0000-000000000422', 'Farmers Carry', 'GRIP', 'Core, Shoulders', 'Equipment', 'COMPOUND', 'INTERMEDIATE', 1, '60s', '0s', 'Pick up two extremely heavy kettlebells or dumbbells and walk forward with perfect upright posture. This simple yet brutal exercise builds bone-crushing grip strength and bulletproofs the core and traps.', NOW()),
('e2500001-0000-0000-0000-000000000423', 'Lunges (Weighted)', 'LEGS', 'Glutes, Core', 'Equipment', 'COMPOUND', 'INTERMEDIATE', 3, '20', '0s', 'Perform walking lunges while holding dumbbells or carrying a barbell across the back, gently kissing the trailing knee to the floor on every rep. This builds massive unilateral leg strength and glute endurance.', NOW()),
('e2500001-0000-0000-0000-000000000424', 'Muscle-ups', 'UPPER BODY', 'Back, Chest', 'Bodyweight', 'COMPOUND', 'EXPERT', 2, '3', '0s', 'Utilize an explosive pull-up to launch your torso over the bar or rings, transitioning smoothly into a deep dip before pressing to lockout. This is the crown jewel of bodyweight pulling and pressing mastery.', NOW()),
('e2500001-0000-0000-0000-000000000425', 'Recovery Walk', 'RECOVERY', 'Cardio', 'Bodyweight', 'ISOLATION', 'BEGINNER', 1, '180s', '0s', 'Walk slowly around the gym floor immediately following a devastating WOD. This is critical for bringing the heart rate down safely, flushing metabolic waste from the muscles, and mentally recovering from the effort.', NOW())
ON CONFLICT (id) DO NOTHING;

